LWpInt := 1/Sqrt[2] * (uqbar[cc, ff1].Ga[mu].(gR*Cos[zeta]*VRqq[ff1,ff2]*Exp[I*omega]*ProjP + gL*Sin[zeta]*VLqq[ff1,ff2]*ProjM).dq[cc, ff2] * Wp[mu] + vlbar[ff1].Ga[mu].(gL*Sin[zeta]*VLll[ff1,ff2]*ProjM).l[ff2] * Wp[mu] + nuRbar[ff1].Ga[mu].(gR*Cos[zeta]*VRll[ff1,ff2]*Exp[I*omega]*ProjP).l[ff2] * Wp[mu]);

LTotal := LWpKin + LNuRKin + LWpInt + HC[LWpInt];
